// ---- týdenní report z listů leads + deals ----
function buildReport(leads, deals, days) {
  const tz = env('OWNER_TZ', 'Europe/Prague');
  const now = DateTime.now().setZone(tz);
  const since = now.minus({ days });
  const inRange = (s) => { const d = parseISO(s); return !!(d && d >= since); };
  const byStatus = {};
  for (const l of leads) { const s = l.status || '?'; byStatus[s] = (byStatus[s] || 0) + 1; }
  const newLeads = leads.filter(l => inRange(l.created_at)).length;
  const previews = leads.filter(l => inRange(l.created_at) && l.preview_url).length;
  const approved = leads.filter(l => inRange(l.approved_at)).length;
  const sent1 = leads.filter(l => inRange(l.sent_1_at)).length;
  const sentAll = leads.filter(l => inRange(l.sent_1_at)).length + leads.filter(l => inRange(l.sent_2_at)).length + leads.filter(l => inRange(l.sent_3_at)).length;
  const replies = leads.filter(l => inRange(l.last_reply_at)).length;
  const positive = leads.filter(l => inRange(l.last_reply_at) && ['interested', 'negotiating', 'won'].includes(l.status)).length;
  const negotiating = leads.filter(l => l.status === 'negotiating').length;
  const wonDeals = deals.filter(d => inRange(d.won_at));
  const revenue = {};
  for (const d of wonDeals) { const c = String(d.currency || 'CZK').toUpperCase(); revenue[c] = (revenue[c] || 0) + (Number(d.price_final) || Number(d.price_quoted) || 0); }
  const segs = {};
  for (const l of leads) {
    if (!l.sent_1_at) continue;
    const key = `${l.country || '?'}/${l.industry || l.category || '?'}`;
    segs[key] = segs[key] || { sent: 0, replied: 0, won: 0 };
    segs[key].sent++; if (l.last_reply_at) segs[key].replied++; if (l.status === 'won') segs[key].won++;
  }
  const top = Object.entries(segs).filter(([k, v]) => v.sent >= 5)
    .map(([k, v]) => ({ segment: k, ...v, reply_rate: v.replied / v.sent })).sort((a, b) => b.reply_rate - a.reply_rate).slice(0, 5);
  const waiting = (byStatus.awaiting_approval || 0);
  const needs = (byStatus.needs_email || 0);
  const revTxt = Object.keys(revenue).length ? Object.entries(revenue).map(([c, v]) => `${Math.round(v).toLocaleString('cs-CZ')} ${c}`).join(' + ') : '0';
  const text = [
    `📊 <b>Týdenní report</b> (${since.toFormat('d. L.')} – ${now.toFormat('d. L. yyyy')})`,
    `Nové firmy: <b>${newLeads}</b> · náhledy: <b>${previews}</b> · schváleno: <b>${approved}</b>`,
    `Odesláno 1. e-mailů: <b>${sent1}</b> (všech: ${sentAll}) · odpovědi: <b>${replies}</b> (pozitivní ${positive}, ${sent1 ? Math.round(100 * replies / Math.max(sent1, 1)) : 0} %)`,
    `Vyjednávání: <b>${negotiating}</b> · zakázky: <b>${wonDeals.length}</b> · tržby: <b>${revTxt}</b>`,
    `Čeká na schválení: ${waiting} · chybí e-mail: ${needs}`,
    '',
    '<b>Stavy celkem:</b> ' + Object.entries(byStatus).sort((a, b) => b[1] - a[1]).map(([k, v]) => `${k} ${v}`).join(' · '),
    top.length ? '\n<b>Top segmenty (odpovědi / odeslané):</b>\n' + top.map(t => `• ${esc(t.segment)}: ${Math.round(100 * t.reply_rate)} % (${t.replied}/${t.sent}, won ${t.won})`).join('\n') : '\nSegmenty: zatím málo dat (min. 5 odeslaných na segment).',
  ].join('\n');
  const short = `${newLeads} nových, ${sent1} odesláno, ${replies} odpovědí, ${wonDeals.length} zakázek (${revTxt})`;
  return { text, short, numbers: { newLeads, previews, approved, sent1, sentAll, replies, positive, negotiating, won: wonDeals.length, revenue, waiting, needs, byStatus, top }, since: since.toISO(), until: now.toISO() };
}

const leads = clean(($('Agregace (MCP report)').first().json.data || []).map(j => ({ json: j })));
const deals = clean($input.all());
const body = ($('Interní: report').first().json || {}).body || {};
const days = Math.min(Math.max(Number(body.days) || 7, 1), 365);
const r = buildReport(leads, deals, days);
