const update = { id: lead.id, status: 'won', price_quoted: lead.price_quoted || price || '', next_action: '', notes: [lead.notes, `${now.toFormat('d.L.')} WON ${price} ${currency} (MCP)`].filter(Boolean).join(' | ').slice(-1000) };
return [{ json: { ok: true, deal, update, name: lead.name, msg: `🏆 <b>${esc(lead.name)}</b> (${esc(lead.city)}, ${esc(lead.country)}) – zakázka ${price} ${currency} uložena (přes MCP).` } }];
